@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Space+Grotesk:wght@400;500;600;700&display=swap');
:root{--ink:#131a14;--paper:#f0eee3;--muted:#8e9385;--lime:#c7f36a;--orange:#ff7448;--purple:#8f67d7;--mono:'DM Mono',monospace;--sans:'Space Grotesk',sans-serif}*{box-sizing:border-box}body{margin:0;background:#111712;color:var(--paper);font-family:var(--sans);min-height:100vh;display:flex;align-items:center;justify-content:center;padding:22px;background-image:radial-gradient(ellipse at 42% 3%,#263225 0,transparent 55%)}button{font:inherit}.game-shell{width:min(1360px,100%);background:#191f19;border:1px solid #323a30;box-shadow:0 32px 100px #0008;padding:0 25px 14px;overflow:hidden}.topbar{height:61px;border-bottom:1px solid #343a30;display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:center;gap:10px;color:#f1f0e5;text-decoration:none;font-size:13px;font-weight:700;letter-spacing:.13em}.brand-mark{background:var(--lime);color:#182017;width:24px;height:24px;display:grid;place-items:center;font-size:14px;clip-path:polygon(0 0,100% 0,100% 73%,50% 100%,0 73%)}.brand-light{font-weight:400;color:#aab09f}.chapter,.sound-button{font-family:var(--mono);font-size:10px;letter-spacing:.08em;color:#a7ad9c}.chapter-name{color:#dedbc9}.live-dot{display:inline-block;width:6px;height:6px;background:var(--lime);border-radius:100%;margin-right:8px;box-shadow:0 0 10px #c7f36a}.sound-button{background:none;color:#c5cab8;border:1px solid #3c453a;border-radius:20px;padding:8px 11px;cursor:pointer}.sound-button span:first-child{color:var(--lime);margin-right:5px}.game-layout{display:grid;grid-template-columns:minmax(0,1fr) 278px;gap:19px;padding:18px 0 0}.game-column{min-width:0}.hud{height:48px;display:flex;align-items:flex-start;justify-content:space-between;padding:1px 5px 0}.hud-label,.personality-title,.mission-title{font:9px var(--mono);letter-spacing:.12em;color:#9da394}.hud-value{font-size:21px;font-weight:700;line-height:1.2}.hud-value small{font:10px var(--mono);color:#9ba191;margin-left:4px}.spark-value{color:var(--paper)}.spark-icon{color:var(--lime);font-size:19px;margin-right:5px}.route-track{height:2px;background:#41473a;position:relative;flex:1;margin:20px 42px 0;max-width:380px}.route-fill{background:var(--lime);width:0;height:100%;transition:width .2s}.route-start,.route-end{font:8px var(--mono);color:#898f80;position:absolute;top:8px}.route-start{left:0}.route-end{right:0}.route-car{position:absolute;top:-9px;left:0%;color:var(--lime);font-size:15px;transform:translateX(-50%);transition:left .2s}.viewport{height:clamp(340px,43vw,550px);min-height:340px;max-height:550px;position:relative;overflow:hidden;background:#d5a96c;border:1px solid #3a4034;isolation:isolate}canvas{width:100%;height:100%;display:block}.scene-tag{position:absolute;top:13px;left:15px;font:9px var(--mono);letter-spacing:.06em;color:#292d24;background:#f4e3bfcc;padding:8px 10px;pointer-events:none}.sun-icon{font-size:12px;color:#ef8650;margin-right:5px}.tag-divider{color:#a67d5b;margin:0 5px}.weather{position:absolute;top:14px;right:15px;font:9px var(--mono);color:#35392c;background:#f4e3bfcc;padding:7px 9px;pointer-events:none}.weather:first-letter{color:#ef8650}.weather span{margin-left:5px}.controls-row{height:55px;display:flex;align-items:center;justify-content:space-between;padding:0 4px}.control-help{font:9px var(--mono);letter-spacing:.06em;color:#a9ae9d;display:flex;align-items:center;gap:5px}.keycap{padding:4px 6px;border:1px solid #4a5144;border-radius:3px;color:#ece9d9}.help-divider{margin:0 5px;color:#737b6b}.boost-meter{display:flex;align-items:center;gap:8px}.boost-label{font:8px var(--mono);letter-spacing:.08em;color:#9fa594}.meter{height:5px;width:82px;background:#353d32;border-radius:4px;overflow:hidden}.meter i{height:100%;width:100%;display:block;background:var(--lime);transition:width .15s}.copilot-panel{background:#222920;border:1px solid #394135;position:relative;min-height:0;padding:16px 16px 12px;display:flex;flex-direction:column}.panel-top{font:9px var(--mono);letter-spacing:.11em;color:#aeb3a4;display:flex;justify-content:space-between;align-items:center}.online{font-size:8px;color:#a8af9e;letter-spacing:.03em}.online i{display:inline-block;width:5px;height:5px;border-radius:50%;background:#a5e774;margin-right:4px}.mox-portrait{height:193px;position:relative;overflow:hidden;background:#33372c;margin:15px 0 12px;display:flex;align-items:flex-end;justify-content:center}.portrait-glow{position:absolute;width:170px;height:145px;border-radius:50%;background:#9472d5;filter:blur(34px);opacity:.44;top:0;left:50%;transform:translateX(-50%)}.mox-art{position:absolute;width:158px;height:150px;left:50%;bottom:13px;transform:translateX(-50%);animation:moxBob 3s ease-in-out infinite}.mox-body{position:absolute;width:116px;height:103px;background:linear-gradient(145deg,#b18ced,#8059c4);border:4px solid #553d7e;border-radius:48% 49% 38% 40%;left:21px;top:42px;box-shadow:inset -12px -8px #694b9b}.horn{position:absolute;z-index:2;top:28px;width:27px;height:29px;background:#f3c970;border:3px solid #553d7e;clip-path:polygon(50% 0,100% 100%,0 100%)}.horn-left{left:42px;transform:rotate(-25deg)}.horn-right{right:39px;transform:rotate(25deg)}.mox-ear{position:absolute;z-index:0;top:74px;width:34px;height:30px;background:#9c79d4;border:3px solid #553d7e;border-radius:50%}.ear-left{left:7px;transform:rotate(-25deg)}.ear-right{right:7px;transform:rotate(25deg)}.mox-eye{position:absolute;z-index:3;top:73px;width:25px;height:29px;background:#fff9e8;border:2px solid #513a76;border-radius:50%}.eye-left{left:52px}.eye-right{right:50px}.mox-eye i{position:absolute;width:9px;height:13px;border-radius:50%;background:#292c35;top:9px;left:8px}.mox-eye i:after{content:'';position:absolute;width:3px;height:4px;border-radius:50%;background:white;top:2px;left:2px}.mox-cheek{position:absolute;z-index:3;top:103px;width:15px;height:8px;background:#e8979b;border-radius:50%;opacity:.9}.cheek-left{left:37px}.cheek-right{right:36px}.mox-mouth{position:absolute;z-index:4;top:106px;left:69px;width:22px;height:15px;border:2px solid #503971;border-top:0;border-radius:0 0 50% 50%;background:#502d57}.mox-tooth{position:absolute;z-index:5;top:108px;left:77px;width:7px;height:5px;background:#fff4d8;border-radius:0 0 3px 3px}.mox-freckle{position:absolute;z-index:4;width:3px;height:3px;border-radius:50%;background:#f4c976;top:99px}.f1{left:51px}.f2{left:57px;top:101px}.f3{right:49px}.f4{right:55px;top:101px}.portrait-name{position:absolute;z-index:5;bottom:7px;left:10px;font:9px var(--mono);letter-spacing:.09em;color:#ece6d8}.portrait-name span{margin-left:7px;color:#c7f36a;font-size:8px}.mox-badge{position:absolute;right:11px;bottom:8px;width:20px;height:20px;background:var(--lime);border-radius:50%;color:#26301d;display:grid;place-items:center;font-size:12px}.mox-intro{background:#30372d;padding:11px 11px 10px;position:relative;min-height:74px;border-left:2px solid var(--lime)}.quote-mark{position:absolute;left:9px;top:3px;font-family:Georgia,serif;color:#c7f36a;font-size:23px}.mox-intro p{font-size:12px;line-height:1.5;margin:5px 0 0 16px;color:#e5e3d6}.personality{padding:15px 1px 13px;border-bottom:1px solid #3b4338}.personality p{font-size:11px;color:#b9beae;margin:7px 0 10px}.personality strong{color:#f2efdf;font-weight:600}.traits{display:flex;gap:5px;flex-wrap:wrap}.traits span{font:7px var(--mono);letter-spacing:.04em;color:#c3caaf;border:1px solid #4a5544;padding:4px 5px}.mission-card{display:flex;gap:11px;align-items:flex-start;background:#2c342a;padding:11px;margin-top:12px}.mission-icon{width:24px;height:24px;display:grid;place-items:center;color:#151c14;background:var(--lime);font-size:16px;flex-shrink:0}.mission-title{font-size:8px}.mission-card p{font-size:10px;line-height:1.5;color:#b9beae;margin:5px 0 0}.mission-card b{color:#f1efdf;font-weight:500}.panel-footer{display:flex;justify-content:space-between;font:7px var(--mono);letter-spacing:.06em;color:#7f8879;margin-top:auto;padding-top:13px}.bottom-note{height:28px;border-top:1px solid #343a30;display:flex;align-items:flex-end;justify-content:space-between;font:8px var(--mono);letter-spacing:.07em;color:#777f70}.bottom-note span:nth-child(2){color:#abb19f}.start-overlay,.finish-overlay{position:absolute;inset:0;z-index:4;display:flex;align-items:center;justify-content:flex-start;background:linear-gradient(90deg,rgba(23,30,22,.86) 0%,rgba(23,30,22,.68) 43%,rgba(23,30,22,.05) 100%);overflow:hidden}.start-overlay.hidden,.finish-overlay.hidden{display:none}.overlay-sun{position:absolute;width:270px;height:270px;border-radius:50%;right:10%;top:10%;background:#f4bd65;opacity:.82;box-shadow:0 0 90px #f4bd6555}.intro-copy{position:relative;z-index:2;margin-left:7%;margin-top:5px}.eyebrow{font:9px var(--mono);color:var(--lime);letter-spacing:.14em;display:flex;align-items:center;gap:8px}.eyebrow-line{width:20px;height:1px;background:var(--lime)}h1{font-size:clamp(38px,5vw,63px);line-height:.96;letter-spacing:-.07em;margin:19px 0 14px;font-weight:700;color:#f4f0dc}h1 em,.finish-card h2 em{font-style:normal;color:var(--lime)}.intro-copy p{font-size:12px;line-height:1.65;color:#dedbc7;margin:0 0 20px}.start-button{background:var(--lime);border:0;color:#1b2418;padding:12px 17px;font:700 10px var(--mono);letter-spacing:.1em;cursor:pointer;transition:transform .15s,background .15s}.start-button:hover{transform:translateY(-2px);background:#d7ff86}.start-button span{font-size:16px;margin-left:17px}.start-hint{font:8px var(--mono);letter-spacing:.08em;color:#c1c3ac;margin-top:12px}.intro-car{position:absolute;right:15%;bottom:19%;font-size:80px;filter:drop-shadow(0 12px 6px #35281f77);transform:scaleX(-1);animation:carIdle 2s ease-in-out infinite}.intro-mox{position:absolute;right:7%;bottom:18%;font-size:41px;filter:drop-shadow(0 6px 6px #32234c);animation:moxBob 2s ease-in-out infinite}.intro-mox span{position:absolute;top:44px;left:5px;font:7px var(--mono);color:#fff}.toast{position:absolute;z-index:3;top:54px;left:50%;transform:translate(-50%,-10px);background:#1e281dcc;border:1px solid #8eae56;color:#def5b3;padding:8px 13px;font:10px var(--mono);letter-spacing:.04em;opacity:0;transition:.25s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.finish-overlay{justify-content:center;background:#111a12c9;backdrop-filter:blur(3px)}.finish-card{background:#222920;border:1px solid #607444;padding:25px 35px;text-align:center;width:min(380px,90%);box-shadow:0 18px 80px #1119}.finish-stars{color:var(--lime);letter-spacing:7px;font-size:19px;margin-bottom:13px}.finish-card .eyebrow{justify-content:center}.finish-card h2{font-size:31px;line-height:.98;letter-spacing:-.06em;margin:14px 0}.finish-card p{font-size:11px;line-height:1.6;color:#c3c6b8}.finish-score{display:flex;justify-content:center;gap:30px;border-top:1px solid #414a3a;border-bottom:1px solid #414a3a;padding:11px;margin:15px 0;font:8px var(--mono);color:#aab29e;letter-spacing:.08em}.finish-score b{font-size:13px;color:var(--lime);margin-right:4px}.touch-controls{display:none}
@keyframes moxBob{0%,100%{translate:0 0}50%{translate:0 -5px}}@keyframes carIdle{0%,100%{translate:0 0}50%{translate:0 -4px}}
@media(max-width:850px){body{padding:0;background:#191f19;align-items:flex-start}.game-shell{border:0;padding:0 14px 12px;box-shadow:none}.game-layout{grid-template-columns:minmax(0,1fr) 235px;gap:12px}.copilot-panel{padding:12px}.mox-portrait{height:160px}.mox-art{transform:translateX(-50%) scale(.88);transform-origin:bottom center}.viewport{height:clamp(330px,49vw,480px)}.chapter-name{display:none}.bottom-note span:last-child{display:none}}
@media(max-width:620px){.game-shell{padding:0 10px 10px}.topbar{height:48px}.chapter{font-size:8px}.sound-label{display:none}.sound-button{padding:6px 8px}.game-layout{display:flex;flex-direction:column;padding-top:10px;gap:9px}.hud{height:43px}.route-track{margin-left:16px;margin-right:16px}.viewport{height:min(58vh,430px);min-height:310px;max-height:430px}.controls-row{height:67px;padding:0 2px}.control-help{display:none}.boost-meter{gap:5px}.boost-label{font-size:7px}.meter{width:56px}.touch-controls{display:flex;gap:7px}.touch-btn{width:48px;height:46px;border:1px solid #56604c;background:#222b21;color:#e9ebd9;display:flex;flex-direction:column;justify-content:center;align-items:center;font-size:14px;touch-action:none;user-select:none}.touch-btn small{font:7px var(--mono);letter-spacing:.04em;margin-top:2px;color:#aeb49f}.touch-btn.gas{background:var(--lime);border-color:var(--lime);color:#192017}.touch-btn.gas small{color:#34402a}.touch-btn.boost{color:var(--lime)}.copilot-panel{display:grid;grid-template-columns:104px 1fr;grid-template-rows:auto 1fr;gap:0 12px;padding:10px 11px;min-height:131px}.panel-top{grid-column:1/-1;margin-bottom:8px}.mox-portrait{grid-column:1;grid-row:2;height:91px;margin:0}.mox-art{transform:translateX(-50%) scale(.56);transform-origin:bottom center;bottom:8px}.portrait-name{font-size:7px;left:5px;bottom:4px}.portrait-name span{display:none}.mox-badge{width:14px;height:14px;right:5px;bottom:4px;font-size:9px}.mox-intro{grid-column:2;grid-row:2;min-height:0;align-self:stretch;padding:8px}.mox-intro p{font-size:11px;line-height:1.4;margin:5px 0 0 13px}.quote-mark{left:6px;font-size:19px}.personality,.mission-card,.panel-footer{display:none}.bottom-note{font-size:7px;height:24px}.intro-copy{margin-left:6%}.intro-copy p{font-size:10px}.intro-car{font-size:56px;right:11%;bottom:16%}.intro-mox{font-size:31px;right:4%;bottom:16%}.intro-mox span{top:34px}.overlay-sun{width:190px;height:190px;right:6%;top:17%}.start-hint{font-size:7px}.scene-tag{left:8px;top:9px;font-size:7px;padding:6px 7px}.weather{right:8px;top:9px;font-size:7px;padding:6px 7px}}
@media(max-width:370px){.viewport{min-height:290px;height:52vh}.hud-value{font-size:18px}.touch-btn{width:42px}.boost-label{display:none}.chapter{display:none}.intro-copy p br{display:none}}

(() => {
  const canvas = document.querySelector('#gameCanvas');
  const ctx = canvas.getContext('2d');
  const $ = (s) => document.querySelector(s);
  const distanceEl = $('#distance'), sparksEl = $('#sparks'), routeFill = $('#routeFill'), routeCar = $('#routeCar');
  const boostFill = $('#boostFill'), moxLine = $('#moxLine'), toast = $('#toast');
  const startOverlay = $('#startOverlay'), finishOverlay = $('#finishOverlay');
  const TOTAL = 1450, SPARK_TARGET = 8;
  let W = 0, H = 0, dpr = 1, running = false, finished = false, last = 0, elapsed = 0;
  let progress = 0, speed = 0, boost = 100, sparks = 0, truckY = 0, airborne = 0, airVelocity = 0, lean = 0, shake = 0;
  let keys = {}, touch = { gas: false, brake: false, boost: false }, soundOn = true, audioCtx = null;
  let toastTimer, lastLine = 0;
  const sparkSpots = [118, 276, 419, 574, 737, 906, 1084, 1260];
  const hazards = [196, 350, 515, 674, 842, 1000, 1174, 1360];
  const lines = [
    'That hill looks very tall. I vote we be taller.',
    'Spark spotted! My snack radar is also beeping.',
    'You’re doing great, Nova. I’m only holding on a little.',
    'A bump! My ears have their own seatbelts, right?',
    'Pip is gonna love this. Especially the dramatic entrance.',
    'If we go fast enough, the dust can’t catch us. Science!',
    'Look at you go! I’m being brave in your general direction.',
    'Nearly there! I can practically smell Pip’s trail mix.'
  ];
  const clamp = (n, a, b) => Math.max(a, Math.min(b, n));
  const terrain = (m) => {
    const hills = Math.sin(m * .0105) * 22 + Math.sin(m * .023 + 1.4) * 12 + Math.sin(m * .0042 + .4) * 24 + Math.sin(m * .038 + 2.2) * 4;
    const ramps = Math.pow(Math.max(0, Math.sin(m * .0068 + .6)), 8) * 28;
    return H * .75 - hills - ramps;
  };
  function resize() {
    const rect = canvas.getBoundingClientRect();
    dpr = Math.min(window.devicePixelRatio || 1, 2);
    W = Math.max(1, rect.width); H = Math.max(1, rect.height);
    canvas.width = Math.round(W * dpr); canvas.height = Math.round(H * dpr);
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    if (!running) draw(0);
  }
  window.addEventListener('resize', resize);
  function beep(freq = 480, duration = .09, type = 'sine') {
    if (!soundOn) return;
    try {
      audioCtx ||= new (window.AudioContext || window.webkitAudioContext)();
      if (audioCtx.state === 'suspended') audioCtx.resume();
      const osc = audioCtx.createOscillator(), gain = audioCtx.createGain();
      osc.type = type; osc.frequency.setValueAtTime(freq, audioCtx.currentTime);
      osc.frequency.exponentialRampToValueAtTime(Math.max(80, freq * .65), audioCtx.currentTime + duration);
      gain.gain.setValueAtTime(.055, audioCtx.currentTime); gain.gain.exponentialRampToValueAtTime(.001, audioCtx.currentTime + duration);
      osc.connect(gain); gain.connect(audioCtx.destination); osc.start(); osc.stop(audioCtx.currentTime + duration);
    } catch (_) {}
  }
  function say(line, notice) {
    moxLine.textContent = line;
    if (notice) {
      toast.textContent = notice; toast.classList.add('show'); clearTimeout(toastTimer);
      toastTimer = setTimeout(() => toast.classList.remove('show'), 1500);
    }
  }
  function start() {
    if (running) return;
    if (finished) reset();
    running = true; startOverlay.classList.add('hidden'); finishOverlay.classList.add('hidden');
    last = performance.now(); requestAnimationFrame(loop); beep(340, .12);
    say('Road trip mode: ON. Confidence level: pretending.', 'MOX IS RIDING SHOTGUN');
  }
  function reset() {
    progress = 0; speed = 0; boost = 100; sparks = 0; elapsed = 0; airborne = 0; airVelocity = 0; lean = 0;
    finished = false; running = false; lastLine = 0;
    distanceEl.textContent = '0'; sparksEl.textContent = '0'; routeFill.style.width = '0%'; routeCar.style.left = '0%'; boostFill.style.width = '100%';
    say('Okay, Nova. I packed snacks, a map, and absolutely no fear. (Mostly.)');
    startOverlay.classList.remove('hidden'); finishOverlay.classList.add('hidden'); draw(0);
  }
  function endGame() {
    running = false; finished = true; progress = TOTAL;
    $('#finalSparks').textContent = sparks;
    $('#finalTime').textContent = formatTime(elapsed);
    $('#finishMessage').textContent = sparks >= SPARK_TARGET
      ? 'Pip is safe, the truck is muddy, and Mox has a new story.'
      : 'Pip is safe! Mox says the best treasure was the ride together.';
    finishOverlay.classList.remove('hidden');
    say('PIP! I told you we’d make it. I mean, I hoped loudly.', 'FRIENDS REUNITED ✦');
    beep(740, .25, 'triangle'); setTimeout(() => beep(920, .3, 'triangle'), 150);
  }
  function formatTime(s) { return `${Math.floor(s / 60)}:${String(Math.floor(s % 60)).padStart(2, '0')}`; }
  function jump() {
    if (!running || airborne > 0) return;
    airborne = 1; airVelocity = -245; beep(240, .08, 'square');
  }
  function loop(now) {
    if (!running) return;
    const dt = Math.min((now - last) / 1000, .04); last = now;
    update(dt); draw(now / 1000);
    if (progress >= TOTAL) endGame();
    if (running) requestAnimationFrame(loop);
  }
  function update(dt) {
    elapsed += dt;
    const gas = keys.ArrowRight || keys.KeyD || touch.gas;
    const braking = keys.ArrowLeft || keys.KeyA || touch.brake;
    const boosting = (keys.Space || touch.boost) && boost > 0;
    const target = gas ? 154 : 92;
    speed += (target - speed) * dt * (gas ? 1.1 : .55);
    if (braking) speed = Math.max(0, speed - 210 * dt);
    if (boosting) { speed += 170 * dt; boost = Math.max(0, boost - 35 * dt); }
    else boost = Math.min(100, boost + dt * (sparks ? 8 : 4));
    speed = clamp(speed, 0, 250);
    progress += speed * dt / 3.6;
    const slope = terrain(progress + 3) - terrain(progress - 3);
    const targetLean = (keys.ArrowUp || keys.KeyW ? -.14 : 0) + (keys.ArrowDown || keys.KeyS ? .18 : 0) + (boosting ? -.08 : 0);
    lean += (targetLean - lean) * dt * 5;
    if (airborne > 0) {
      airVelocity += 570 * dt; airborne += airVelocity * dt;
      if (airborne <= 0) { airborne = 0; airVelocity = 0; shake = 5; say('Nailed that landing! My tummy is still up there.', 'SOFT LANDING'); }
    } else if (slope < -18 && speed > 105) { airborne = 1; airVelocity = -Math.min(190, speed * .9); }
    if (shake > 0) shake = Math.max(0, shake - dt * 12);
    for (let i = 0; i < sparkSpots.length; i++) {
      const x = sparkSpots[i];
      if (x >= 0 && Math.abs(progress - x) < 9 && airborne < 60) {
        sparkSpots[i] = -1000; sparks++; sparksEl.textContent = sparks;
        boost = Math.min(100, boost + 20); beep(800 + sparks * 35, .13, 'triangle');
        say(sparks % 2 ? 'Shiny! I’ll guard it with my life. And my pockets.' : lines[(sparks + 1) % lines.length], `✦ SPARK FOUND  +1  ·  BOOST +20`);
      }
    }
    for (let i = 0; i < hazards.length; i++) {
      const x = hazards[i];
      if (x >= 0 && Math.abs(progress - x) < 5 && airborne < 10) {
        hazards[i] = -1000; speed *= .55; shake = 7; say('Cactus! It was mostly in my way. Mostly.', 'CACTUS BONK  ·  KEEP ROLLING'); beep(120, .15, 'square');
      }
    }
    const m = Math.floor(progress / 170);
    if (m > lastLine) { lastLine = m; if (m < 8 && Math.random() > .35) say(lines[m % lines.length]); }
    distanceEl.textContent = Math.floor(progress).toString();
    const pct = clamp(progress / TOTAL * 100, 0, 100);
    routeFill.style.width = `${pct}%`; routeCar.style.left = `${pct}%`;
    boostFill.style.width = `${boost}%`;
