function draw(time = 0) {
  if (!W || !H) return;
  ctx.save();
  const jx = shake ? (Math.random() - .5) * shake : 0;
  ctx.translate(jx, 0);
  const sky = ctx.createLinearGradient(0, 0, 0, H);
  sky.addColorStop(0, '#f4c985'); sky.addColorStop(.58, '#eab576'); sky.addColorStop(1, '#cd9362');
  ctx.fillStyle = sky; ctx.fillRect(-10, 0, W + 20, H);
  // High desert sun and hazy distant mesas.
  ctx.fillStyle = '#fff0bd'; ctx.globalAlpha = .78; ctx.beginPath(); ctx.arc(W * .79, H * .23, Math.min(H * .105, 64), 0, Math.PI * 2); ctx.fill(); ctx.globalAlpha = 1;
  ctx.fillStyle = '#d69467';
  ctx.beginPath(); ctx.moveTo(0, H * .55);
  for (let x = 0; x <= W + 20; x += 4) {
    const wx = progress * .24 + x / W * 5;
    const y = H * .53 + Math.sin(wx * 1.6) * H * .04 + Math.sin(wx * .47) * H * .035;
    ctx.lineTo(x, y);
  }
  ctx.lineTo(W + 20, H); ctx.lineTo(0, H); ctx.closePath(); ctx.fill();
  ctx.fillStyle = '#bb805b'; ctx.beginPath(); ctx.moveTo(0, H * .68);
  for (let x = 0; x <= W + 20; x += 4) {
    const wx = progress * .45 + x / W * 7;
    const y = H * .65 + Math.sin(wx * 1.25 + 2) * H * .045 + Math.sin(wx * .48) * H * .025;
    ctx.lineTo(x, y);
  }
  ctx.lineTo(W + 20, H); ctx.lineTo(0, H); ctx.closePath(); ctx.fill();
  // Ground follows the rolling trail in world coordinates.
  const scale = 1.12, carX = W * .28;
  const worldAt = (sx) => progress + (sx - carX) / scale;
  const groundY = (sx) => terrain(worldAt(sx));
  ctx.beginPath(); ctx.moveTo(-2, H + 5);
  for (let sx = -3; sx <= W + 3; sx += 3) ctx.lineTo(sx, groundY(sx));
  ctx.lineTo(W + 3, H + 5); ctx.closePath();
  const dirt = ctx.createLinearGradient(0, H * .66, 0, H);
  dirt.addColorStop(0, '#b97646'); dirt.addColorStop(.08, '#aa6039'); dirt.addColorStop(1, '#78442f');
  ctx.fillStyle = dirt; ctx.fill();
  ctx.beginPath(); for (let sx = -3; sx <= W + 3; sx += 3) { const y = groundY(sx); if (sx === -3) ctx.moveTo(sx, y); else ctx.lineTo(sx, y); }
  ctx.strokeStyle = '#efd08d'; ctx.lineWidth = 5; ctx.stroke();
  ctx.beginPath(); for (let sx = -3; sx <= W + 3; sx += 3) { const y = groundY(sx) + 4; if (sx === -3) ctx.moveTo(sx, y); else ctx.lineTo(sx, y); }
  ctx.strokeStyle = '#d89a5c'; ctx.lineWidth = 2; ctx.stroke();
  // Little trail marks give the ground a sense of motion.
  for (let i = 0; i < 22; i++) {
    const sx = ((i * 103 - (progress * scale) % 103) + W + 103) % W;
    const sy = groundY(sx) + 20 + (i % 4) * 13;
    ctx.fillStyle = i % 2 ? '#d0925b' : '#8d5038';
    ctx.globalAlpha = .55; ctx.fillRect(sx, sy, 8 + (i % 4) * 3, 2); ctx.globalAlpha = 1;
  }
  // Cacti hazards.
  for (const m of hazards) {
    const sx = carX + (m - progress) * scale;
    if (m < 0 || sx < -40 || sx > W + 40) continue;
    drawCactus(sx, groundY(sx));
  }
  // Collectible golden sparks float just above the path.
  for (const m of sparkSpots) {
    const sx = carX + (m - progress) * scale;
    if (m < 0 || sx < -30 || sx > W + 30) continue;
    const sy = groundY(sx) - 48 - Math.sin(time * 4 + m) * 5;
    ctx.save(); ctx.translate(sx, sy); ctx.rotate(time * 1.5);
    ctx.shadowColor = '#fff09b'; ctx.shadowBlur = 17; ctx.fillStyle = '#fff0a0';
    ctx.beginPath(); ctx.moveTo(0, -11); ctx.lineTo(3, -3); ctx.lineTo(11, 0); ctx.lineTo(3, 3); ctx.lineTo(0, 11); ctx.lineTo(-3, 3); ctx.lineTo(-11, 0); ctx.lineTo(-3, -3); ctx.closePath(); ctx.fill();
    ctx.shadowBlur = 0; ctx.restore();
  }
  // The lookout and Pip wait at the end of the road.
  const finishX = carX + (TOTAL - progress) * scale;
  if (finishX < W + 180 && finishX > -180) drawLookout(finishX, groundY(finishX), time);
  // Car suspension follows the trail; jump height is an actual physics arc.
  const baseY = groundY(carX) - 8 - airborne;
  drawTruck(carX, baseY, time);
  ctx.restore();
}
function drawCactus(x, y) {
  ctx.save(); ctx.translate(x, y);
  ctx.fillStyle = '#477044'; ctx.strokeStyle = '#365837'; ctx.lineWidth = 3;
  ctx.beginPath(); ctx.roundRect(-5, -31, 10, 32, 5); ctx.fill(); ctx.stroke();
  ctx.beginPath(); ctx.roundRect(-15, -23, 9, 20, 5); ctx.fill(); ctx.stroke();
  ctx.beginPath(); ctx.roundRect(-15, -23, 11, 8, 4); ctx.fill();
  ctx.beginPath(); ctx.roundRect(6, -18, 9, 17, 5); ctx.fill(); ctx.stroke();
  ctx.beginPath(); ctx.roundRect(1, -18, 13, 8, 4); ctx.fill();
  ctx.restore();
}
function drawLookout(x, y, time) {
  ctx.save(); ctx.translate(x, y);
  ctx.fillStyle = '#f0d49b'; ctx.fillRect(-3, -86, 6, 86);
  ctx.strokeStyle = '#f0d49b'; ctx.lineWidth = 2; ctx.beginPath(); ctx.moveTo(-3, -76); ctx.lineTo(-24, -45); ctx.moveTo(3, -76); ctx.lineTo(24, -45); ctx.stroke();
  ctx.fillStyle = '#e86d4b'; ctx.beginPath(); ctx.moveTo(-25, -84); ctx.lineTo(30, -84); ctx.lineTo(3, -62); ctx.closePath(); ctx.fill();
  ctx.fillStyle = '#d9f17d'; ctx.beginPath(); ctx.arc(34, -42 + Math.sin(time * 4) * 3, 11, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#584b58'; ctx.beginPath(); ctx.arc(30, -45, 2, 0, 7); ctx.arc(38, -45, 2, 0, 7); ctx.fill();
  ctx.strokeStyle = '#584b58'; ctx.lineWidth = 2; ctx.beginPath(); ctx.arc(34, -41, 4, .2, 2.8); ctx.stroke();
  ctx.fillStyle = '#f5efdd'; ctx.font = '9px monospace'; ctx.textAlign = 'center'; ctx.fillText('PIP!', 0, -92);
  ctx.restore();
}

